-- PostgreSQL production baseline. This is independent of the private D1 preview.
-- Apply to a new database with a dedicated migration role, never from a browser.
BEGIN;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE generation_state AS ENUM ('queued','processing','completed','failed','cancelled','refunded','reconciliation_required');
CREATE TYPE moderation_state AS ENUM ('draft','pending_review','approved','rejected','suspended','removed');
CREATE TYPE credit_type AS ENUM ('purchase','generation_charge','generation_refund','promotion','admin_adjustment','referral_bonus','subscription_credit','marketplace_reward','expiration');
CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL, email_verified_at timestamptz, role text NOT NULL DEFAULT 'user' CHECK(role IN ('user','moderator','admin')), status text NOT NULL DEFAULT 'active', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz);
CREATE UNIQUE INDEX users_email_unique ON users(lower(email)) WHERE deleted_at IS NULL;
CREATE TABLE profiles(user_id uuid PRIMARY KEY REFERENCES users(id),username text NOT NULL UNIQUE,display_name text NOT NULL,bio text,avatar_key text,social_links jsonb NOT NULL DEFAULT '{}',default_private boolean NOT NULL DEFAULT true,interests text[] NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE auth_accounts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),provider text NOT NULL,provider_subject text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(provider,provider_subject));
CREATE TABLE auth_sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),token_hash text NOT NULL UNIQUE,device_name text,expires_at timestamptz NOT NULL,revoked_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE credit_wallets(user_id uuid PRIMARY KEY REFERENCES users(id),balance bigint NOT NULL DEFAULT 0 CHECK(balance>=0),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE credit_packages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,price_cents bigint NOT NULL CHECK(price_cents>0),currency char(3) NOT NULL DEFAULT 'usd',credits bigint NOT NULL CHECK(credits>0),stripe_price_id text UNIQUE,enabled boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE payments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),kind text NOT NULL CHECK(kind IN ('credits','character','subscription')),status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','paid','failed','refunded','partially_refunded','disputed')),amount_cents bigint NOT NULL CHECK(amount_cents>=0),currency char(3) NOT NULL,credits_snapshot bigint CHECK(credits_snapshot>0),stripe_session_id text UNIQUE,stripe_payment_intent_id text UNIQUE,refunded_cents bigint NOT NULL DEFAULT 0 CHECK(refunded_cents>=0),package_id uuid REFERENCES credit_packages(id),idempotency_key text NOT NULL UNIQUE,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(refunded_cents<=amount_cents));
CREATE TABLE subscriptions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),stripe_subscription_id text NOT NULL UNIQUE,status text NOT NULL,period_end timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ai_providers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL UNIQUE,adapter text NOT NULL,secret_env_key text NOT NULL,enabled boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ai_models(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),provider_id uuid NOT NULL REFERENCES ai_providers(id),provider_model_id text NOT NULL,display_name text NOT NULL,generation_type text NOT NULL,enabled boolean NOT NULL DEFAULT false,featured boolean NOT NULL DEFAULT false,parameters_schema jsonb NOT NULL DEFAULT '{}',capabilities jsonb NOT NULL DEFAULT '{}',estimated_seconds integer,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(provider_id,provider_model_id));
CREATE TABLE model_pricing(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),model_id uuid NOT NULL REFERENCES ai_models(id),version integer NOT NULL CHECK(version>0),provider_cost_usd numeric(14,8) NOT NULL CHECK(provider_cost_usd>=0),fixed_credits bigint CHECK(fixed_credits>0),target_gross_margin numeric(6,5) CHECK(target_gross_margin>=0 AND target_gross_margin<1),credit_value_usd numeric(14,8) NOT NULL CHECK(credit_value_usd>0),minimum_credits bigint NOT NULL CHECK(minimum_credits>0),multipliers jsonb NOT NULL DEFAULT '{}',effective_at timestamptz NOT NULL DEFAULT now(),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(model_id,version),CHECK(fixed_credits IS NOT NULL OR target_gross_margin IS NOT NULL));
CREATE TABLE creator_profiles(user_id uuid PRIMARY KEY REFERENCES users(id),bio text,status text NOT NULL DEFAULT 'applied',stripe_connect_account_id text UNIQUE,kyc_status text NOT NULL DEFAULT 'unverified',charges_enabled boolean NOT NULL DEFAULT false,payouts_enabled boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE character_categories(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL UNIQUE,slug text NOT NULL UNIQUE);
CREATE TABLE characters(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),creator_id uuid NOT NULL REFERENCES creator_profiles(user_id),category_id uuid REFERENCES character_categories(id),name text NOT NULL,slug text NOT NULL UNIQUE,description text NOT NULL,style text,gender_presentation text,age_category text NOT NULL DEFAULT 'adult',status moderation_state NOT NULL DEFAULT 'draft',price_cents bigint NOT NULL CHECK(price_cents>=0),currency char(3) NOT NULL DEFAULT 'usd',cover_asset_key text,preview_enabled boolean NOT NULL DEFAULT false,rights_attested_at timestamptz,depicts_real_person boolean NOT NULL DEFAULT false,consent_review_id uuid,search_vector tsvector GENERATED ALWAYS AS(to_tsvector('simple',coalesce(name,'')||' '||coalesce(description,''))) STORED,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz);
CREATE INDEX characters_search ON characters USING gin(search_vector);
CREATE INDEX characters_discovery ON characters(status,category_id,created_at DESC) WHERE deleted_at IS NULL;
CREATE TABLE character_tags(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL UNIQUE);
CREATE TABLE character_tag_links(character_id uuid NOT NULL REFERENCES characters(id),tag_id uuid NOT NULL REFERENCES character_tags(id),PRIMARY KEY(character_id,tag_id));
CREATE TABLE character_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),character_id uuid NOT NULL REFERENCES characters(id),version integer NOT NULL,implementation_type text NOT NULL,private_storage_key text,private_trigger text,recommended_strength numeric(5,3),base_model text,status text NOT NULL DEFAULT 'draft',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(character_id,version));
CREATE TABLE character_assets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),character_id uuid NOT NULL REFERENCES characters(id),version_id uuid REFERENCES character_versions(id),kind text NOT NULL,storage_key text NOT NULL UNIQUE,visibility text NOT NULL DEFAULT 'private' CHECK(visibility IN ('private','public_preview')),mime_type text NOT NULL,size_bytes bigint NOT NULL CHECK(size_bytes>=0),moderation_status moderation_state NOT NULL DEFAULT 'pending_review',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE character_model_bindings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),character_version_id uuid NOT NULL REFERENCES character_versions(id),model_id uuid NOT NULL REFERENCES ai_models(id),private_provider_parameters jsonb NOT NULL DEFAULT '{}',enabled boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(character_version_id,model_id));
CREATE TABLE character_licenses(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),character_id uuid NOT NULL REFERENCES characters(id),version integer NOT NULL,label text NOT NULL,license_text text NOT NULL,commercial_permissions jsonb NOT NULL DEFAULT '{}',prohibited_uses jsonb NOT NULL DEFAULT '[]',downloads_allowed boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(character_id,version));
CREATE TABLE character_purchases(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),character_id uuid NOT NULL REFERENCES characters(id),buyer_id uuid NOT NULL REFERENCES users(id),seller_id uuid NOT NULL REFERENCES creator_profiles(user_id),payment_id uuid NOT NULL UNIQUE REFERENCES payments(id),license_id uuid NOT NULL REFERENCES character_licenses(id),license_version integer NOT NULL,license_text_snapshot text NOT NULL,permissions_snapshot jsonb NOT NULL,prohibited_uses_snapshot jsonb NOT NULL,price_cents bigint NOT NULL CHECK(price_cents>=0),currency char(3) NOT NULL,status text NOT NULL DEFAULT 'active',created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX character_active_ownership ON character_purchases(buyer_id,character_id) WHERE status='active';
CREATE TABLE collections(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),name text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,name));
CREATE TABLE collection_characters(collection_id uuid NOT NULL REFERENCES collections(id),purchase_id uuid NOT NULL REFERENCES character_purchases(id),PRIMARY KEY(collection_id,purchase_id));
CREATE TABLE projects(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),name text NOT NULL,description text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz);
CREATE TABLE generations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),model_id uuid NOT NULL REFERENCES ai_models(id),character_version_id uuid REFERENCES character_versions(id),purchase_id uuid REFERENCES character_purchases(id),parent_generation_id uuid REFERENCES generations(id),prompt text NOT NULL,parameters jsonb NOT NULL,pricing_snapshot jsonb NOT NULL,credit_cost bigint NOT NULL CHECK(credit_cost>0),provider_cost_usd numeric(14,8),state generation_state NOT NULL DEFAULT 'queued',private boolean NOT NULL DEFAULT true,idempotency_key text NOT NULL UNIQUE,request_hash text NOT NULL,provider_request_id text,error_code text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX generations_user_history ON generations(user_id,created_at DESC);
CREATE TABLE generation_jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),generation_id uuid NOT NULL UNIQUE REFERENCES generations(id),state text NOT NULL DEFAULT 'queued',attempts integer NOT NULL DEFAULT 0,available_at timestamptz NOT NULL DEFAULT now(),lease_until timestamptz,lease_owner uuid,submitted_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX jobs_ready ON generation_jobs(available_at) WHERE state IN ('queued','polling');
CREATE TABLE generation_assets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),generation_id uuid NOT NULL REFERENCES generations(id),user_id uuid NOT NULL REFERENCES users(id),storage_key text NOT NULL UNIQUE,mime_type text NOT NULL,size_bytes bigint NOT NULL CHECK(size_bytes>=0),width integer,height integer,duration_ms integer,seed bigint,metadata jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE project_assets(project_id uuid NOT NULL REFERENCES projects(id),asset_id uuid NOT NULL REFERENCES generation_assets(id),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(project_id,asset_id));
CREATE TABLE project_references(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES projects(id),user_id uuid NOT NULL REFERENCES users(id),private_storage_key text NOT NULL,mime_type text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE credit_transactions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES credit_wallets(user_id),amount bigint NOT NULL,type credit_type NOT NULL,generation_id uuid REFERENCES generations(id),payment_id uuid REFERENCES payments(id),description text NOT NULL,balance_before bigint NOT NULL CHECK(balance_before>=0),balance_after bigint NOT NULL CHECK(balance_after>=0),idempotency_key text NOT NULL UNIQUE,created_at timestamptz NOT NULL DEFAULT now(),CHECK(balance_before+amount=balance_after));
CREATE INDEX credit_transactions_history ON credit_transactions(user_id,created_at DESC);
CREATE TABLE marketplace_rules(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),version integer NOT NULL UNIQUE,platform_fee_bps integer NOT NULL CHECK(platform_fee_bps BETWEEN 0 AND 10000),reserve_bps integer NOT NULL CHECK(reserve_bps BETWEEN 0 AND 10000),reserve_days integer NOT NULL CHECK(reserve_days>=0),usage_royalties_enabled boolean NOT NULL DEFAULT false,royalty_configuration jsonb NOT NULL DEFAULT '{}',effective_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE creator_balances(creator_id uuid PRIMARY KEY REFERENCES creator_profiles(user_id),pending_cents bigint NOT NULL DEFAULT 0 CHECK(pending_cents>=0),available_cents bigint NOT NULL DEFAULT 0 CHECK(available_cents>=0),reserve_cents bigint NOT NULL DEFAULT 0 CHECK(reserve_cents>=0),currency char(3) NOT NULL DEFAULT 'usd',updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE creator_transactions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),creator_id uuid NOT NULL REFERENCES creator_profiles(user_id),purchase_id uuid REFERENCES character_purchases(id),rule_id uuid REFERENCES marketplace_rules(id),kind text NOT NULL,gross_cents bigint NOT NULL,tax_cents bigint NOT NULL,platform_fee_cents bigint NOT NULL,reserve_cents bigint NOT NULL,seller_net_cents bigint NOT NULL,currency char(3) NOT NULL,available_at timestamptz,idempotency_key text NOT NULL UNIQUE,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX seller_transactions_history ON creator_transactions(creator_id,created_at DESC);
CREATE TABLE payouts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),creator_id uuid NOT NULL REFERENCES creator_profiles(user_id),amount_cents bigint NOT NULL CHECK(amount_cents>0),currency char(3) NOT NULL,status text NOT NULL,stripe_transfer_id text UNIQUE,stripe_payout_id text UNIQUE,idempotency_key text NOT NULL UNIQUE,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE reviews(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),purchase_id uuid NOT NULL UNIQUE REFERENCES character_purchases(id),user_id uuid NOT NULL REFERENCES users(id),character_id uuid NOT NULL REFERENCES characters(id),rating integer NOT NULL CHECK(rating BETWEEN 1 AND 5),body text,status text NOT NULL DEFAULT 'pending',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE publications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),asset_id uuid NOT NULL UNIQUE REFERENCES generation_assets(id),show_prompt boolean NOT NULL DEFAULT false,remix_enabled boolean NOT NULL DEFAULT false,status moderation_state NOT NULL DEFAULT 'pending_review',created_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz);
CREATE TABLE likes(user_id uuid NOT NULL REFERENCES users(id),publication_id uuid NOT NULL REFERENCES publications(id),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,publication_id));
CREATE TABLE favorites(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),character_id uuid REFERENCES characters(id),asset_id uuid REFERENCES generation_assets(id),created_at timestamptz NOT NULL DEFAULT now(),CHECK(num_nonnulls(character_id,asset_id)=1));
CREATE UNIQUE INDEX favorites_character_unique ON favorites(user_id,character_id) WHERE character_id IS NOT NULL;
CREATE UNIQUE INDEX favorites_asset_unique ON favorites(user_id,asset_id) WHERE asset_id IS NOT NULL;
CREATE TABLE follows(follower_id uuid NOT NULL REFERENCES users(id),creator_id uuid NOT NULL REFERENCES creator_profiles(user_id),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(follower_id,creator_id),CHECK(follower_id<>creator_id));
CREATE TABLE notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),type text NOT NULL,payload jsonb NOT NULL,read_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX notifications_unread ON notifications(user_id,created_at DESC) WHERE read_at IS NULL;
CREATE TABLE reports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),reporter_id uuid REFERENCES users(id),character_id uuid REFERENCES characters(id),publication_id uuid REFERENCES publications(id),kind text NOT NULL,description text NOT NULL,evidence_private_key text,status text NOT NULL DEFAULT 'open',created_at timestamptz NOT NULL DEFAULT now(),CHECK(num_nonnulls(character_id,publication_id)=1));
CREATE TABLE moderation_cases(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),report_id uuid REFERENCES reports(id),character_id uuid REFERENCES characters(id),reviewer_id uuid REFERENCES users(id),status text NOT NULL DEFAULT 'open',decision text,consent_evidence_key text,created_at timestamptz NOT NULL DEFAULT now(),resolved_at timestamptz);
ALTER TABLE characters ADD CONSTRAINT characters_consent_case FOREIGN KEY(consent_review_id) REFERENCES moderation_cases(id);
CREATE TABLE promo_codes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code text NOT NULL UNIQUE,credits bigint NOT NULL CHECK(credits>0),max_redemptions integer NOT NULL CHECK(max_redemptions>0),expires_at timestamptz,enabled boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE promo_redemptions(promo_id uuid NOT NULL REFERENCES promo_codes(id),user_id uuid NOT NULL REFERENCES users(id),transaction_id uuid NOT NULL REFERENCES credit_transactions(id),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(promo_id,user_id));
CREATE TABLE audit_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),actor_id uuid REFERENCES users(id),action text NOT NULL,entity_type text NOT NULL,entity_id uuid,metadata jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE webhooks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),provider text NOT NULL,external_id text NOT NULL,payload_hash text NOT NULL,status text NOT NULL DEFAULT 'pending',attempts integer NOT NULL DEFAULT 0,received_at timestamptz NOT NULL DEFAULT now(),processed_at timestamptz,UNIQUE(provider,external_id));
CREATE TABLE system_settings(key text PRIMARY KEY,value jsonb NOT NULL,updated_by uuid REFERENCES users(id),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE feature_flags(key text PRIMARY KEY,enabled boolean NOT NULL DEFAULT false,configuration jsonb NOT NULL DEFAULT '{}',updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE support_tickets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),subject text NOT NULL,body text NOT NULL,status text NOT NULL DEFAULT 'open',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE FUNCTION immutable_record() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Immutable record: write a compensating transaction'; END $$;
CREATE TRIGGER immutable_credit BEFORE UPDATE OR DELETE ON credit_transactions FOR EACH ROW EXECUTE FUNCTION immutable_record();
CREATE TRIGGER immutable_seller BEFORE UPDATE OR DELETE ON creator_transactions FOR EACH ROW EXECUTE FUNCTION immutable_record();
CREATE TRIGGER immutable_license BEFORE UPDATE OR DELETE ON character_licenses FOR EACH ROW EXECUTE FUNCTION immutable_record();
CREATE TRIGGER immutable_audit BEFORE UPDATE OR DELETE ON audit_logs FOR EACH ROW EXECUTE FUNCTION immutable_record();
CREATE TRIGGER immutable_purchase_snapshot BEFORE UPDATE OF character_id,buyer_id,seller_id,payment_id,license_id,license_version,license_text_snapshot,permissions_snapshot,prohibited_uses_snapshot,price_cents,currency ON character_purchases FOR EACH ROW EXECUTE FUNCTION immutable_record();
-- All application credit writes use this locked, idempotent function.
CREATE FUNCTION post_credit_entry(p_user uuid,p_amount bigint,p_type credit_type,p_description text,p_key text,p_generation uuid DEFAULT NULL,p_payment uuid DEFAULT NULL) RETURNS credit_transactions LANGUAGE plpgsql AS $$
DECLARE b bigint; prior credit_transactions; result credit_transactions;
BEGIN
 SELECT balance INTO b FROM credit_wallets WHERE user_id=p_user FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Wallet not found'; END IF;
 SELECT * INTO prior FROM credit_transactions WHERE idempotency_key=p_key;
 IF FOUND THEN
  IF prior.user_id<>p_user OR prior.amount<>p_amount OR prior.type<>p_type OR prior.generation_id IS DISTINCT FROM p_generation OR prior.payment_id IS DISTINCT FROM p_payment THEN RAISE EXCEPTION 'Idempotency key payload conflict'; END IF;
  RETURN prior;
 END IF;
 IF b+p_amount<0 THEN RAISE EXCEPTION 'Insufficient credits'; END IF;
 INSERT INTO credit_transactions(user_id,amount,type,generation_id,payment_id,description,balance_before,balance_after,idempotency_key) VALUES(p_user,p_amount,p_type,p_generation,p_payment,p_description,b,b+p_amount,p_key) RETURNING * INTO result;
 UPDATE credit_wallets SET balance=b+p_amount,updated_at=now() WHERE user_id=p_user;
 RETURN result;
END $$;
CREATE VIEW wallet_reconciliation AS SELECT w.user_id,w.balance,coalesce(sum(t.amount),0) AS ledger_balance FROM credit_wallets w LEFT JOIN credit_transactions t ON t.user_id=w.user_id GROUP BY w.user_id,w.balance HAVING w.balance<>coalesce(sum(t.amount),0);
COMMIT;
